CREATE OR REPLACE VIEW "EXT"."CSA_LC_RPA_DETALLE_SVW" ( "TIPO_INFORME", "PERIODO", "PERIODO_FORMATO", "COD_AGENTE", "NOMBRE_AGENTE", "NIF", "NIF_NOMBRE", "TIPO_AGENTE", "COD_AGENTE_TABLA", "ID_PROD", "COD_POLIZA", "PRODUCTO", "TIPO_RECIBO", "FECHA_EMISION", "FECHA_COBRO", "POL_FIS", "POL_CORR", "PRIMA", "ASEG", "SOLO_DIFERENCIAS", "FEC_ACTUALIZACION", "POSITIONSEQ", "PERIODSEQ" ) AS 
(SELECT "TIPO_INFORME" , "PERIODO" , "PERIODO_FORMATO" , "COD_AGENTE" , "NOMBRE_AGENTE" , "NIF" , "NIF_NOMBRE" , "TIPO_AGENTE" , "COD_AGENTE_TABLA" , "ID_PROD" , "COD_POLIZA" , "PRODUCTO" , "TIPO_RECIBO" , "FECHA_EMISION" , "FECHA_COBRO" , "POL_FIS" , "POL_CORR" , "PRIMA" , "ASEG" , "SOLO_DIFERENCIAS" , "FEC_ACTUALIZACION" , "POSITIONSEQ" , "PERIODSEQ" FROM EXT.OUT_RPA_DETALLE_FINAL_REP
	WHERE TIPO_INFORME = 'LC'
		AND PERIODSEQ IN (SELECT PERIODSEQ FROM EXT.LIB_CREAR_TABLAS:N_MESES(13))) WITH STRUCTURED PRIVILEGE CHECK;